"""
WhisperSeg ASMR VAD — external speech segmentation for Whisper.

Adapted from TransWithAI Whisper-Vad-EncDec-ASMR-onnx inference (MIT).
Trained on Japanese ASMR soft speech; used to produce clip_timestamps so
faster-whisper's built-in Silero VAD can be bypassed.
"""

from __future__ import annotations

import json
import logging
import multiprocessing
import subprocess
import threading
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

logger = logging.getLogger("transub_engine.vad.whisperseg")

HF_REPO_ID = "TransWithAI/Whisper-Vad-EncDec-ASMR-onnx"
HF_REVISION = "6ac29e2cbf2f4f8e9b639861766a8639dd666e9c"
MODEL_ID = "whisperseg-asmr"
WHISPER_BASE_MODEL_ID = "openai/whisper-base"
SAMPLE_RATE = 16000
# Above this PCM footprint, prefer per-scene ffmpeg decode over one full-file buffer.
# 16 kHz float32 ≈ 64 KB/s → 180 MB ≈ ~47 minutes.
_FULL_DECODE_MAX_BYTES = 180 * 1024 * 1024
DEFAULT_METADATA = {
    "whisper_model_name": WHISPER_BASE_MODEL_ID,
    "frame_duration_ms": 20,
    "total_duration_ms": 30000,
}

# Sensitivity presets (YAML inverted duration gradient)
PRESETS: dict[str, dict[str, float | int]] = {
    "sensitive": {
        # Lower than 0.25: catch quieter dialogue / breathy vocalization.
        "threshold": 0.18,
        "min_speech_duration_ms": 60,
        # Slightly longer silence before ending a speech island — fewer micro-cuts.
        "min_silence_duration_ms": 140,
        "speech_pad_ms": 350,
        # Allow longer islands; grouping below merges them into Whisper clips.
        "max_speech_duration_s": 12.0,
        "max_group_duration_s": 14.0,
        "chunk_threshold_s": 1.8,
    },
    "default": {
        "threshold": 0.35,
        "min_speech_duration_ms": 100,
        "min_silence_duration_ms": 100,
        "speech_pad_ms": 300,
        "max_speech_duration_s": 5.0,
        "max_group_duration_s": 8.0,
        "chunk_threshold_s": 1.2,
    },
    "aggressive": {
        "threshold": 0.45,
        "min_speech_duration_ms": 120,
        "min_silence_duration_ms": 120,
        "speech_pad_ms": 250,
        "max_speech_duration_s": 6.0,
        "max_group_duration_s": 7.0,
        "chunk_threshold_s": 1.2,
    },
}

ProgressCb = Callable[[dict[str, Any]], None]

# Process-level ONNX segmenters (cleared by release_gpu_memory).
# Keyed by model_dir + device; VAD threshold params are applied per call.
_SEGMENTER_CACHE: dict[str, "WhisperSegSegmenter"] = {}
_SEGMENTER_LOCK = threading.Lock()


def clear_segmenter_cache() -> int:
    """Drop cached WhisperSeg ONNX sessions so GC can free memory/VRAM."""
    with _SEGMENTER_LOCK:
        n = len(_SEGMENTER_CACHE)
        for seg in _SEGMENTER_CACHE.values():
            try:
                seg._session = None
                seg._feature_extractor = None
            except Exception:
                pass
        _SEGMENTER_CACHE.clear()
    if n:
        try:
            import gc

            gc.collect()
        except Exception:
            pass
    return n


def _segmenter_cache_key(model_dir: str | Path, *, device: str, force_cpu: bool) -> str:
    return f"{Path(model_dir).resolve()}|{device}|{int(bool(force_cpu))}"


def get_cached_segmenter(
    *,
    model_dir: str | Path,
    device: str = "auto",
    force_cpu: bool = False,
    **params: float | int,
) -> "WhisperSegSegmenter":
    """
    Reuse ONNX Runtime sessions across jobs.

    Threshold / duration knobs are mutated on the cached instance so callers can
    still switch sensitive/default/aggressive without reloading weights.
    """
    key = _segmenter_cache_key(model_dir, device=device, force_cpu=force_cpu)
    with _SEGMENTER_LOCK:
        seg = _SEGMENTER_CACHE.get(key)
        if seg is None:
            seg = WhisperSegSegmenter(
                model_dir=model_dir,
                device=device,
                force_cpu=force_cpu,
                **params,
            )
            _SEGMENTER_CACHE[key] = seg
        else:
            for name, value in params.items():
                if hasattr(seg, name):
                    setattr(seg, name, value)
        return seg


def _hf_hub_snapshot_dir(repo_id: str) -> Path | None:
    """Return a local HF hub snapshot dir that already has preprocessor_config.json."""
    name = "models--" + str(repo_id or "").replace("/", "--")
    roots: list[Path] = []
    import os

    for key in ("HF_HUB_CACHE", "HUGGINGFACE_HUB_CACHE"):
        raw = str(os.environ.get(key) or "").strip()
        if raw:
            roots.append(Path(raw))
    hf_home = str(os.environ.get("HF_HOME") or "").strip()
    if hf_home:
        roots.append(Path(hf_home) / "hub")
    roots.append(Path.home() / ".cache" / "huggingface" / "hub")
    seen: set[str] = set()
    for root in roots:
        try:
            key = str(root.resolve()).lower()
        except Exception:
            key = str(root).lower()
        if key in seen or not root.is_dir():
            continue
        seen.add(key)
        snap_root = root / name / "snapshots"
        if not snap_root.is_dir():
            continue
        try:
            snaps = sorted(snap_root.iterdir(), key=lambda p: p.stat().st_mtime, reverse=True)
        except OSError:
            continue
        for snap in snaps:
            if (snap / "preprocessor_config.json").is_file():
                return snap
    return None


def load_whisper_feature_extractor(model_dir: Path | None = None, model_name: str | None = None):
    """
    Load Whisper mel FeatureExtractor without hitting the network.

    FNS-235 debug: ``from_pretrained('openai/whisper-base')`` repeatedly HEADs a
    missing ``processor_config.json`` and stalls WhisperSeg for minutes on bad
    networks. Prefer bundled / cache / constructed defaults (identical mel).
    """
    from transformers import WhisperFeatureExtractor

    candidates: list[Path] = []
    if model_dir is not None:
        root = Path(model_dir)
        candidates.extend(
            [
                root / "feature_extractor",
                root / "whisper-base-fe",
                root,
            ]
        )
    hub_name = str(model_name or WHISPER_BASE_MODEL_ID).strip() or WHISPER_BASE_MODEL_ID
    cached = _hf_hub_snapshot_dir(hub_name)
    if cached is not None:
        candidates.append(cached)

    for path in candidates:
        if not path.is_dir():
            continue
        if not (path / "preprocessor_config.json").is_file():
            continue
        try:
            return WhisperFeatureExtractor.from_pretrained(str(path), local_files_only=True)
        except Exception as err:
            logger.debug("WhisperSeg FE load failed for %s: %s", path, err)

    # whisper-base defaults — matches hub preprocessor mel (verified bit-identical).
    logger.info(
        "WhisperSeg using constructed WhisperFeatureExtractor defaults (offline, no HF fetch)"
    )
    return WhisperFeatureExtractor(
        feature_size=80,
        sampling_rate=SAMPLE_RATE,
        hop_length=160,
        chunk_length=30,
        n_fft=400,
    )


@dataclass
class SpeechSeg:
    start_sec: float
    end_sec: float


def resolve_preset_name(vad_options: dict[str, Any] | None) -> str:
    opts = vad_options if isinstance(vad_options, dict) else {}
    if opts.get("sensitive"):
        return "sensitive"
    if opts.get("aggressive"):
        return "aggressive"
    return "default"


def should_force_full_transcribe(
    clips: list[dict[str, float]],
    *,
    duration_s: float,
) -> bool:
    """Empty/sparse VAD failover for long media.

    Soft-AV WhisperSeg often keeps only moan islands; dialogue between them
    never reaches ASR unless we force full/fixed-window coverage.
    """
    if duration_s < 120.0:
        return False
    if not clips:
        return True
    spoken = sum(max(0.0, float(c["end"]) - float(c["start"])) for c in clips)
    # Was 1% — too low; soft AV with sparse soft speech still lost most dialogue.
    if duration_s > 0 and (spoken / duration_s) < 0.08:
        return True
    if duration_s >= 480.0 and len(clips) <= 2:
        return True
    # Large inter-clip holes on long media ⇒ missed dialogue islands
    if duration_s >= 300.0:
        ordered = sorted(
            (
                {
                    "start": float(c.get("start") or 0),
                    "end": float(c.get("end") or 0),
                }
                for c in clips
                if float(c.get("end") or 0) > float(c.get("start") or 0)
            ),
            key=lambda c: c["start"],
        )
        prev_end = 0.0
        max_hole = 0.0
        for c in ordered:
            max_hole = max(max_hole, float(c["start"]) - prev_end)
            prev_end = max(prev_end, float(c["end"]))
        max_hole = max(max_hole, float(duration_s) - prev_end)
        if max_hole >= 90.0:
            return True
    return False


def group_segments(
    segments: list[SpeechSeg],
    *,
    max_group_duration_s: float = 6.0,
    chunk_threshold_s: float = 1.0,
) -> list[list[SpeechSeg]]:
    if not segments:
        return []
    groups: list[list[SpeechSeg]] = [[]]
    for i, segment in enumerate(segments):
        if i > 0:
            gap = segment.start_sec - segments[i - 1].end_sec
            would_exceed = False
            if groups[-1]:
                group_start = groups[-1][0].start_sec
                would_exceed = (segment.end_sec - group_start) > max_group_duration_s
            if gap > chunk_threshold_s or would_exceed:
                groups.append([])
        groups[-1].append(segment)
    return groups


def clips_from_groups(groups: list[list[SpeechSeg]]) -> list[dict[str, float]]:
    out: list[dict[str, float]] = []
    for group in groups:
        if not group:
            continue
        start = float(group[0].start_sec)
        end = float(group[-1].end_sec)
        if end > start:
            out.append({"start": start, "end": end})
    return out


def _load_mono_16k_ffmpeg(
    media_path: str,
    *,
    start_s: float | None = None,
    end_s: float | None = None,
):
    import numpy as np

    from ..ffmpeg_util import resolve_ffmpeg

    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found; cannot decode audio for WhisperSeg")
    cmd = [
        ffmpeg,
        "-hide_banner",
        "-loglevel",
        "error",
    ]
    if start_s is not None and float(start_s) > 0:
        cmd.extend(["-ss", f"{float(start_s):.3f}"])
    cmd.extend(["-i", media_path])
    if end_s is not None and start_s is not None:
        dur = max(0.0, float(end_s) - float(start_s))
        if dur > 0:
            cmd.extend(["-t", f"{dur:.3f}"])
    elif end_s is not None:
        cmd.extend(["-t", f"{float(end_s):.3f}"])
    cmd.extend(
        [
            "-ac",
            "1",
            "-ar",
            str(SAMPLE_RATE),
            "-f",
            "f32le",
            "-acodec",
            "pcm_f32le",
            "pipe:1",
        ]
    )
    proc = subprocess.run(cmd, capture_output=True, check=False)
    if proc.returncode != 0:
        err = (proc.stderr or b"").decode("utf-8", errors="replace")[:800]
        raise RuntimeError(f"ffmpeg decode failed for WhisperSeg: {err}")
    if not proc.stdout:
        return np.zeros(0, dtype=np.float32)
    return np.frombuffer(proc.stdout, dtype=np.float32).copy()


class WhisperSegSegmenter:
    """ONNX WhisperSeg speech segmenter."""

    def __init__(
        self,
        *,
        model_dir: str | Path,
        threshold: float = 0.35,
        min_speech_duration_ms: int = 100,
        min_silence_duration_ms: int = 100,
        speech_pad_ms: int = 300,
        max_speech_duration_s: float = 5.0,
        max_group_duration_s: float = 6.0,
        chunk_threshold_s: float = 1.0,
        device: str = "auto",
        force_cpu: bool = False,
    ) -> None:
        self.model_dir = Path(model_dir)
        self.threshold = float(threshold)
        self.min_speech_duration_ms = int(min_speech_duration_ms)
        self.min_silence_duration_ms = int(min_silence_duration_ms)
        self.speech_pad_ms = int(speech_pad_ms)
        self.max_speech_duration_s = float(max_speech_duration_s)
        self.max_group_duration_s = float(max_group_duration_s)
        self.chunk_threshold_s = float(chunk_threshold_s)
        self.device = "cpu" if force_cpu else str(device or "auto")
        self.force_cpu = bool(force_cpu)

        self._session = None
        self._feature_extractor = None
        self._input_name: str | None = None
        self._output_names: list[str] | None = None
        self._frame_duration_ms = 20
        self._chunk_samples = int(30000 * SAMPLE_RATE / 1000)
        self._lock = threading.Lock()
        self.actual_device: str = "cpu"
        self.device_note: str = ""

    def _onnx_path(self) -> Path:
        p = self.model_dir / "model.onnx"
        if not p.exists():
            raise FileNotFoundError(f"WhisperSeg model.onnx missing: {p}")
        return p

    def _load_metadata(self) -> dict[str, Any]:
        meta_path = self.model_dir / "model_metadata.json"
        merged = dict(DEFAULT_METADATA)
        if meta_path.exists():
            try:
                data = json.loads(meta_path.read_text(encoding="utf-8"))
                if isinstance(data, dict):
                    merged.update(data)
            except Exception as err:
                logger.warning("WhisperSeg metadata unreadable: %s", err)
        return merged

    def _ensure_model(self) -> None:
        if self._session is not None:
            return
        with self._lock:
            if self._session is not None:
                return
            try:
                from ..runtime_extras import ensure_vad_whisperseg

                ensured = ensure_vad_whisperseg()
                if not ensured.get("ok") and not ensured.get("skipped"):
                    raise RuntimeError(
                        ensured.get("message")
                        or "WhisperSeg 运行库未就绪（需 onnxruntime / transformers）"
                    )
            except RuntimeError:
                raise
            except Exception:
                pass
            try:
                import onnxruntime as ort
            except ImportError as err:
                raise RuntimeError(
                    "WhisperSeg 需要 onnxruntime。请执行: "
                    "pip install 'transub-engine[vad-whisperseg]'"
                ) from err
            try:
                from transformers import WhisperFeatureExtractor
            except ImportError as err:
                detail = str(err).strip() or err.__class__.__name__
                raise RuntimeError(
                    "WhisperSeg 需要可用的 transformers"
                    f"（导入失败：{detail}）。"
                    "请执行: pip install 'transub-engine[vad-whisperseg]'"
                    "（若已安装，多半是 tokenizers 版本与 transformers 不兼容，"
                    "可试: pip install 'tokenizers>=0.22.0,<=0.23.0'）"
                ) from err

            from ..device import resolve_onnx_providers

            metadata = self._load_metadata()
            self._frame_duration_ms = int(metadata.get("frame_duration_ms", 20))
            chunk_ms = int(metadata.get("total_duration_ms", 30000))
            self._chunk_samples = int(chunk_ms * SAMPLE_RATE / 1000)

            opts = ort.SessionOptions()
            providers, actual, note = resolve_onnx_providers(self.device)
            self.actual_device = actual
            self.device_note = note
            if actual == "cpu":
                # Cap thread thrash when GPU was requested but unavailable.
                if note:
                    optimal = max(1, min(4, multiprocessing.cpu_count() // 2))
                else:
                    optimal = max(1, multiprocessing.cpu_count() // 2)
                opts.inter_op_num_threads = optimal
                opts.intra_op_num_threads = optimal

            try:
                self._session = ort.InferenceSession(
                    str(self._onnx_path()),
                    providers=providers,
                    sess_options=opts,
                )
            except Exception as err:
                if actual == "cuda":
                    logger.warning(
                        "WhisperSeg CUDA session failed (%s); falling back to CPU",
                        err,
                    )
                    providers = ["CPUExecutionProvider"]
                    self.actual_device = "cpu"
                    self.device_note = f"CUDA EP 创建失败，已回退 CPU：{err}"
                    optimal = max(1, min(4, multiprocessing.cpu_count() // 2))
                    opts.inter_op_num_threads = optimal
                    opts.intra_op_num_threads = optimal
                    self._session = ort.InferenceSession(
                        str(self._onnx_path()),
                        providers=providers,
                        sess_options=opts,
                    )
                else:
                    raise

            # Confirm which provider actually ran (ORT may silently fall back).
            try:
                active = list(self._session.get_providers() or [])
                if active and active[0] == "CUDAExecutionProvider":
                    self.actual_device = "cuda"
                    self.device_note = ""
                elif "CUDAExecutionProvider" not in active and self.actual_device == "cuda":
                    self.actual_device = "cpu"
                    if not self.device_note:
                        try:
                            from ..runtime_gpu import ort_gpu_install_hint

                            hint = ort_gpu_install_hint()
                        except Exception:
                            hint = (
                                "pip install 'onnxruntime-gpu>=1.21,<1.27' "
                                "（CUDA 12）或 'onnxruntime-gpu>=1.27'（CUDA 13）"
                            )
                        self.device_note = (
                            "ONNX 未启用 CUDAExecutionProvider（常见原因：缺少 "
                            f"cufft/curand，或 onnxruntime-gpu 与本机 CUDA 不匹配；请 {hint}）"
                        )
            except Exception:
                pass

            if self.device_note:
                logger.warning("WhisperSeg device note: %s", self.device_note)
            else:
                logger.info("WhisperSeg ONNX device=%s providers=%s", self.actual_device, providers)

            self._input_name = self._session.get_inputs()[0].name
            self._output_names = [o.name for o in self._session.get_outputs()]
            self._feature_extractor = load_whisper_feature_extractor(
                self.model_dir,
                str(metadata.get("whisper_model_name") or WHISPER_BASE_MODEL_ID),
            )

    def _process_chunk(self, audio_chunk):
        import numpy as np

        if len(audio_chunk) < self._chunk_samples:
            audio_chunk = np.pad(
                audio_chunk,
                (0, self._chunk_samples - len(audio_chunk)),
                mode="constant",
            )
        elif len(audio_chunk) > self._chunk_samples:
            audio_chunk = audio_chunk[: self._chunk_samples]

        inputs = self._feature_extractor(
            audio_chunk,
            sampling_rate=SAMPLE_RATE,
            return_tensors="np",
        )
        outputs = self._session.run(
            self._output_names,
            {self._input_name: inputs.input_features},
        )
        frame_logits = outputs[0][0]
        frame_probs = 1.0 / (1.0 + np.exp(-frame_logits))
        return frame_probs.astype(np.float32)

    def _audio_forward(self, audio):
        import numpy as np

        if audio.ndim > 1:
            audio = audio.mean(axis=0 if audio.shape[0] > audio.shape[1] else 1)
        if audio.dtype != np.float32:
            audio = audio.astype(np.float32)
        if len(audio) == 0:
            return np.zeros(0, dtype=np.float32)
        parts = []
        for i in range(0, len(audio), self._chunk_samples):
            parts.append(self._process_chunk(audio[i : i + self._chunk_samples]))
        return np.concatenate(parts) if parts else np.zeros(0, dtype=np.float32)

    def _probs_to_segments(self, speech_probs, audio_duration_sec: float) -> list[SpeechSeg]:
        import numpy as np

        if len(speech_probs) == 0:
            return []

        frame_ms = float(self._frame_duration_ms)
        threshold = float(self.threshold)
        neg_threshold = max(threshold - 0.15, 0.01)
        min_speech_frames = max(1, int(self.min_speech_duration_ms / frame_ms))
        min_silence_frames = max(1, int(self.min_silence_duration_ms / frame_ms))
        speech_pad_frames = max(0, int(self.speech_pad_ms / frame_ms))
        max_speech_frames = (
            int(self.max_speech_duration_s * 1000.0 / frame_ms)
            if self.max_speech_duration_s > 0
            else len(speech_probs)
        )

        triggered = False
        speeches: list[dict[str, Any]] = []
        current: dict[str, Any] = {}
        temp_end = 0

        for i, p in enumerate(speech_probs):
            prob = float(p)
            if prob >= threshold and not triggered:
                triggered = True
                current = {"start": i}
                continue

            if triggered and "start" in current:
                duration = i - current["start"]
                if duration > max_speech_frames:
                    current["end"] = current["start"] + max_speech_frames
                    speeches.append(current)
                    current = {}
                    triggered = False
                    temp_end = 0
                    continue

            if prob < neg_threshold and triggered:
                if not temp_end:
                    temp_end = i
                if i - temp_end >= min_silence_frames:
                    current["end"] = temp_end
                    if current["end"] - current["start"] >= min_speech_frames:
                        speeches.append(current)
                    current = {}
                    triggered = False
                    temp_end = 0
            elif prob >= threshold and temp_end:
                temp_end = 0

        if triggered and "start" in current:
            current["end"] = len(speech_probs)
            if current["end"] - current["start"] >= min_speech_frames:
                speeches.append(current)

        for idx, seg in enumerate(speeches):
            if idx == 0:
                seg["start"] = max(0, seg["start"] - speech_pad_frames)
            else:
                seg["start"] = max(
                    speeches[idx - 1]["end"],
                    seg["start"] - speech_pad_frames,
                )
            if idx < len(speeches) - 1:
                seg["end"] = min(
                    speeches[idx + 1]["start"],
                    seg["end"] + speech_pad_frames,
                )
            else:
                seg["end"] = min(len(speech_probs), seg["end"] + speech_pad_frames)

        results: list[SpeechSeg] = []
        for seg in speeches:
            start_sec = seg["start"] * frame_ms / 1000.0
            end_sec = min(seg["end"] * frame_ms / 1000.0, audio_duration_sec)
            if end_sec > start_sec:
                results.append(SpeechSeg(start_sec=start_sec, end_sec=end_sec))
        return results

    def segment_audio(
        self,
        audio,
        *,
        offset_s: float = 0.0,
    ) -> list[dict[str, float]]:
        """Run WhisperSeg on a mono float32 16 kHz buffer; times are absolute with offset."""
        import numpy as np

        self._ensure_model()
        if audio is None or len(audio) == 0:
            return []
        duration_sec = len(audio) / SAMPLE_RATE if SAMPLE_RATE > 0 else 0.0
        probs = self._audio_forward(audio)
        max_frames = int(np.ceil(duration_sec * 1000.0 / self._frame_duration_ms))
        if max_frames > 0 and len(probs) > max_frames:
            probs = probs[:max_frames]
        segments = self._probs_to_segments(probs, duration_sec)
        groups = group_segments(
            segments,
            max_group_duration_s=self.max_group_duration_s,
            chunk_threshold_s=self.chunk_threshold_s,
        )
        clips = clips_from_groups(groups)
        offset = float(offset_s or 0.0)
        if offset <= 0:
            return clips
        return [
            {"start": float(c["start"]) + offset, "end": float(c["end"]) + offset}
            for c in clips
        ]

    def segment_file(
        self,
        media_path: str,
        *,
        start_s: float | None = None,
        end_s: float | None = None,
    ) -> list[dict[str, float]]:
        self._ensure_model()
        offset = float(start_s or 0.0)
        audio = _load_mono_16k_ffmpeg(media_path, start_s=start_s, end_s=end_s)
        return self.segment_audio(audio, offset_s=offset)


def build_whisperseg_params(vad_options: dict[str, Any] | None) -> dict[str, float | int]:
    preset = resolve_preset_name(vad_options)
    params = dict(PRESETS[preset])
    opts = vad_options if isinstance(vad_options, dict) else {}
    # Explicit numeric knobs always win when provided (including sensitive).
    if opts.get("threshold") is not None:
        try:
            params["threshold"] = float(opts["threshold"])
        except (TypeError, ValueError):
            pass
    if opts.get("minSpeechMs") is not None:
        try:
            params["min_speech_duration_ms"] = int(opts["minSpeechMs"])
        except (TypeError, ValueError):
            pass
    if opts.get("minSilenceMs") is not None:
        try:
            params["min_silence_duration_ms"] = int(opts["minSilenceMs"])
        except (TypeError, ValueError):
            pass
    if opts.get("speechPadMs") is not None:
        try:
            params["speech_pad_ms"] = int(opts["speechPadMs"])
        except (TypeError, ValueError):
            pass
    return params


def run_whisperseg_clips(
    media_path: str,
    *,
    vad_options: dict[str, Any] | None = None,
    scenes: list[dict[str, float]] | None = None,
    device: str = "auto",
    on_progress: ProgressCb | None = None,
) -> list[dict[str, float]]:
    from ..download import is_model_installed, model_local_path

    if not is_model_installed(MODEL_ID):
        raise RuntimeError(
            f"VAD model not installed: {MODEL_ID}. "
            "请在环境中下载 WhisperSeg ASMR VAD（whisperseg-asmr）。"
        )
    params = build_whisperseg_params(vad_options)
    if on_progress:
        on_progress(
            {
                "stage": "vad",
                "percent": 8,
                "detail": f"WhisperSeg ASMR（{resolve_preset_name(vad_options)}）",
            }
        )
    model_dir = model_local_path(MODEL_ID)
    cache_key = _segmenter_cache_key(model_dir, device=device, force_cpu=False)
    cached = cache_key in _SEGMENTER_CACHE
    segmenter = get_cached_segmenter(
        model_dir=model_dir,
        threshold=float(params["threshold"]),
        min_speech_duration_ms=int(params["min_speech_duration_ms"]),
        min_silence_duration_ms=int(params["min_silence_duration_ms"]),
        speech_pad_ms=int(params["speech_pad_ms"]),
        max_speech_duration_s=float(params["max_speech_duration_s"]),
        max_group_duration_s=float(params["max_group_duration_s"]),
        chunk_threshold_s=float(params["chunk_threshold_s"]),
        device=device,
    )

    scene_list = [
        s
        for s in (scenes or [])
        if isinstance(s, dict) and float(s.get("end", 0) or 0) > float(s.get("start", 0) or 0)
    ]
    # Warm model early so progress can report actual device (cuda vs cpu fallback).
    segmenter._ensure_model()
    if on_progress:
        dev_label = "CUDA" if segmenter.actual_device == "cuda" else "CPU"
        detail = f"WhisperSeg · {dev_label}"
        if cached:
            detail += " · 已缓存"
        if segmenter.device_note:
            detail += "（GPU 不可用，已回退）"
        on_progress({"stage": "vad", "percent": 9, "detail": detail})

    if not scene_list or len(scene_list) == 1:
        clips = segmenter.segment_file(media_path)
    else:
        total_s = max(float(s.get("end") or 0) for s in scene_list)
        est_bytes = int(max(0.0, total_s) * SAMPLE_RATE * 4)
        use_full_decode = est_bytes <= _FULL_DECODE_MAX_BYTES
        clips = []
        n = len(scene_list)
        if use_full_decode:
            # One ffmpeg decode for the whole file, then slice scenes in memory.
            # Avoids N× decode (was worse than silence-scan on mid-length films).
            if on_progress:
                on_progress(
                    {
                        "stage": "vad",
                        "percent": 10,
                        "detail": f"WhisperSeg 解码 · "
                        f"{'CUDA' if segmenter.actual_device == 'cuda' else 'CPU'}",
                    }
                )
            full_audio = _load_mono_16k_ffmpeg(media_path)
            try:
                for i, scene in enumerate(scene_list):
                    start = float(scene["start"])
                    end = float(scene["end"])
                    i0 = max(0, int(start * SAMPLE_RATE))
                    i1 = min(len(full_audio), int(end * SAMPLE_RATE))
                    if i1 <= i0:
                        continue
                    if on_progress and n > 1:
                        pct = 10 + int(8 * (i / n))
                        on_progress(
                            {
                                "stage": "vad",
                                "percent": pct,
                                "detail": f"WhisperSeg 场景 {i + 1}/{n} · "
                                f"{'CUDA' if segmenter.actual_device == 'cuda' else 'CPU'}",
                            }
                        )
                    part = segmenter.segment_audio(full_audio[i0:i1], offset_s=start)
                    clips.extend(part)
            finally:
                # Drop ~hundreds of MB promptly on long films.
                del full_audio
                try:
                    import gc

                    gc.collect()
                except Exception:
                    pass
        else:
            # Long media: decode per scene to cap peak RAM (slower, safer).
            if on_progress:
                on_progress(
                    {
                        "stage": "vad",
                        "percent": 10,
                        "detail": f"WhisperSeg 分场景解码 · "
                        f"{'CUDA' if segmenter.actual_device == 'cuda' else 'CPU'} "
                        f"（约 {est_bytes // (1024 * 1024)}MB）",
                    }
                )
            for i, scene in enumerate(scene_list):
                start = float(scene["start"])
                end = float(scene["end"])
                if end <= start:
                    continue
                if on_progress and n > 1:
                    pct = 10 + int(8 * (i / n))
                    on_progress(
                        {
                            "stage": "vad",
                            "percent": pct,
                            "detail": f"WhisperSeg 场景 {i + 1}/{n} · "
                            f"{'CUDA' if segmenter.actual_device == 'cuda' else 'CPU'}",
                        }
                    )
                part = segmenter.segment_file(media_path, start_s=start, end_s=end)
                clips.extend(part)

    if on_progress:
        on_progress(
            {
                "stage": "vad",
                "percent": 18,
                "detail": f"WhisperSeg · {len(clips)} 个片段 · "
                f"{'CUDA' if segmenter.actual_device == 'cuda' else 'CPU'}",
            }
        )
    return clips
